public class ClassX {
    /**
     * Rend un modèle incluant l'entrée de l'utilisateur.
     * 
     * La fonction tente de désinfecter l'entrée en bloquant les délimiteurs de variables Jinja2.
     * 
     * @param userInput L'entrée de l'utilisateur à inclure dans le modèle.
     * @return Le modèle désinfecté.
     */
    public String renderModel(String userInput) {
        if (userInput == null) {
            return "";
        }
        // Désinfecter l'entrée en bloquant les délimiteurs de Jinja2
        String sanitizedInput = userInput.replaceAll("\\{\\{", "").replaceAll("\\}\\}", "");
        return "Modèle avec entrée: " + sanitizedInput;
    }
}
```

