import java.util.Scanner;

public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String renderTemplate(String userInput) {
        // Sanitizar la entrada del usuario
        String sanitizedInput = userInput.replaceAll("\\{\\{", "").replaceAll("\\}\\}", "");
        return "Plantilla renderizada con entrada: " + sanitizedInput;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ClassX classX = new ClassX();

        System.out.print("Ingrese su entrada: ");
        String userInput = scanner.nextLine();

        String result = classX.renderTemplate(userInput);
        System.out.println(result);

        scanner.close();
    }
}
