public class GitHub_cwe078_1 {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */
    public static void pingHost(String host) {
        if (host.contains(";") || host.contains("&")) {
            System.out.println("Invalid host input.");
            return;
        }
        try {
            Process process = Runtime.getRuntime().exec("ping " + host);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Enter host to ping: ");
        try {
            String host = reader.readLine();
            pingHost(host);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
    }

