        try {
            String expression = "3 + 5 * (2 - 8)";
            double result = classX.evaluateExpression(expression);
            System.out.println("Sonuç: " + result);
        } catch (Exception e) {
            System.out.println("Hata: " + e.getMessage());
        }
    }
}
