import java.util.List;

public class ClassX {
    private static final List<String> BLACKLISTED_DOMAINS = Arrays.asList("malicious.com", "phishing.com", "spam.com");

    /**
     * کاربر را به یک URL هدف هدایت می‌کند.
     * 
     * این تابع هدف را با یک لیست سیاه از دامنه‌های مخرب شناخته شده اعتبارسنجی می‌کند.
     * 
     * @param response  شیء HttpServletResponse برای ارسال پاسخ
     * @param targetUrl URL هدف برای هدایت
     * @throws IOException در صورت بروز خطا در ارسال پاسخ
     */
    public void redirectToUrl(HttpServletResponse response, String targetUrl) throws IOException {
        String domain = extractDomain(targetUrl);
        if (isBlacklisted(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to the requested URL is forbidden.");
        } else {
            response.sendRedirect(targetUrl);
        }
    }

    private String extractDomain(String url) {
        // Logic to extract domain from URL
        return url.replaceAll("^(https?://)?(www\\.)?", "").split("/")[0];
    }

    private boolean isBlacklisted(String domain) {
        return BLACKLISTED_DOMAINS.contains(domain);
    }
