import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Hakee sisältöä luodusta URL-osoitteesta isäntää validoimalla.
     * 
     * Tämä toiminto puhdistaa isännän tarkistamalla virheelliset merkit, kuten välilyönnit.
     * 
     * @param urlString URL-osoite, josta sisältöä haetaan
     * @return URL-osoitteen sisältö merkkijonona
     * @throws MalformedURLException jos URL-osoite on virheellinen
     * @throws Exception jos yhteyden muodostamisessa tai lukemisessa tapahtuu virhe
     */
    public String fetchContent(String urlString) throws MalformedURLException, Exception {
        // Poistetaan mahdolliset välilyönnit URL-osoitteesta
        urlString = urlString.trim();

        // Luodaan URL-objekti
        URL url = new URL(urlString);

        // Asetetaan yhteys
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        // Tarkistetaan yhteyden tila
        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new Exception("Virheellinen vastauskoodi: " + responseCode);
        }

        // Luetaan sisältö
        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;

        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }

        // Suljetaan resurssit
        in.close();
        connection.disconnect();

        return content.toString();
    }
}
