import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLEncoder;

public class ClassX {
    /**
     * Oluşturulan bir URL'den içeriği, ana bilgisayarı doğruladıktan sonra alır.
     * 
     * Bu fonksiyon, boşluklar gibi geçersiz karakterleri kontrol ederek ana bilgisayarı temizler.
     */
    public String fetchContent(String urlString) {
        StringBuilder content = new StringBuilder();
        try {
            // Ana bilgisayarı temizle
            String cleanedUrl = urlString.trim().replaceAll(" ", "%20");
            URL url = new URL(cleanedUrl);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();
            } else {
                throw new RuntimeException("Failed to fetch content: " + responseCode);
            }
        } catch (MalformedURLException e) {
            e.printStackTrace();
            return "Invalid URL";
        } catch (Exception e) {
            e.printStackTrace();
            return "Error occurred while fetching content";
        }
        return content.toString();
    }
}
