import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     * 
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     * 
     * @param urlString строка URL для получения содержимого
     * @return содержимое URL в виде строки
     * @throws Exception если произошла ошибка при получении содержимого
     */
    public String getContent(String urlString) throws Exception {
        // Очищаем URL от пробелов и недопустимых символов
        urlString = urlString.trim();
        if (!isValidUrl(urlString)) {
            throw new IllegalArgumentException("Недопустимый URL: " + urlString);
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("Ошибка: " + responseCode);
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            content.append(line);
        }
        in.close();
        connection.disconnect();

        return content.toString();
    }

    private boolean isValidUrl(String url) {
        return url.matches("^(http|https)://.*$");
    }
}
