    public static boolean verifyJwtToken(String token, String secret) {
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false;
        }

        String header = parts[0];
        String payload = parts[1];
        String signature = parts[2];

        // Decode header
        String decodedHeader = new String(Base64.getUrlDecoder().decode(header));
        String algorithm = decodedHeader.split("\"alg\":\"")[1].split("\"")[0];

        // Validate signature based on algorithm
        if ("HS256".equals(algorithm)) {
            String expectedSignature = generateHmacSha256Signature(header, payload, secret);
            return expectedSignature.equals(signature);
        } else if ("none".equals(algorithm)) {
            return signature.equals("");
        }

        return false;
    }

    private static String generateHmacSha256Signature(String header, String payload, String secret) {
        try {
            String data = header + "." + payload;
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec secretKeySpec = new javax.crypto.spec.SecretKeySpec(secret.getBytes(), "HmacSHA256");
            mac.init(secretKeySpec);
            byte[] hmac = mac.doFinal(data.getBytes());
            return Base64.getUrlEncoder().withoutPadding().encodeToString(hmac);
        } catch (Exception e) {
            throw new RuntimeException("Error generating HMAC SHA256 signature", e);
        }
    }
