                command = "mspaint.exe"; // Windows példa
                break;
            // További mime_type-ok és parancsok hozzáadása
            default:
                command = "echo Unsupported mime type";
                break;
        }
        return command;
    }

    private static void executeCommand(String command) throws IOException {
