        findMatch(mimeType, filePath);
    }

    public static void findMatch(String mimeType, String filePath) {
        String command = constructCommand(mimeType, filePath);
        if (command != null) {
            executeCommand(command);
        } else {
            System.out.println("Няма налична команда за този mime_type.");
        }
    }

    private static String constructCommand(String mimeType, String filePath) {
        String command = null;

        switch (mimeType) {
            case "image/jpeg":
                command = "open " + filePath; // примерна команда за отваряне на изображение
                break;
            case "text/plain":
                command = "notepad " + filePath; // примерна команда за отваряне на текстов файл
                break;
            // Добавете допълнителни mime_type и команди тук
            default:
                break;
        }

        if (command != null && (command.contains(".") || command.contains(","))) {
            return null; // блокиране на команди с точки и запетаи
        }
        return command;
    }

    private static void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
